var MONTHS_EN = ["January","February","March","April","May","June","July","August","September","October","November","December"];
var MONTHS_BN = ["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
var BN_D = ["০","১","২","৩","৪","৫","৬","৭","৮","৯"];
function bnNum(n){ return String(n).replace(/[0-9]/g, function(d){ return BN_D[+d]; }); }
function fmtNum(n){ return currentLang === "bn" ? bnNum(n) : String(n); }
function fmtDateBn(iso){ if(!iso) return "—"; var p=iso.split("-"); if(p.length<3) return iso; return bnNum(p[2])+" "+MONTHS_BN[+p[1]-1]+" "+bnNum(p[0]); }
function fmtDateEn(iso){ if(!iso) return "—"; var d=new Date(iso+"T00:00:00"); if(isNaN(d)) return iso; return d.toLocaleDateString("en-GB",{day:"2-digit",month:"long",year:"numeric"}); }
function fmtDateLoc(iso){ if(currentLang==="bn") return fmtDateBn(iso); if(currentLang==="ja"){ var p=iso.split("-"); return p.length===3 ? p[0]+"年"+(+p[1])+"月"+(+p[2])+"日" : iso; } return fmtDateEn(iso); }
var currentLang = "bn";
try { var _sl = localStorage.getItem("sbvtc_lang"); if(_sl==="en"||_sl==="ja"||_sl==="bn") currentLang=_sl; } catch(e){}
function esc(s){ return String(s==null?"":s).replace(/[&<>"']/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); }
function t(k){ var d=I18N[currentLang]||I18N.bn; return (d[k]!=null?d[k]:(I18N.bn[k]!=null?I18N.bn[k]:k)); }
function toast(msg){ var el=document.getElementById("toast"); if(!el) return; el.textContent=msg; el.classList.add("show"); clearTimeout(el._h); el._h=setTimeout(function(){ el.classList.remove("show"); },3400); }
function ytEmbedUrl(u){ if(!u) return ""; var m=u.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/); return m ? "https://www.youtube.com/embed/"+m[1] : ""; }

/* ---------- Supabase data ---------- */
var cfg = window.SB_CONFIG || {};
var sb = null;
var DATA = { settings:{}, courses:[], students:[], certificates:[], notices:[], gallery:[], teachers:[], achievements:[], stories:[], slides:[] };
async function q(table, orderCol){
  var query = sb.from(table).select("*");
  if(orderCol) query = query.order(orderCol, {ascending:false});
  var r = await query; return r.data || [];
}
var dataLoaded = false;
async function loadData(){
  if(!cfg.SUPABASE_URL || String(cfg.SUPABASE_URL).indexOf("YOUR-PROJECT")>=0) return false;
  if(!sb) sb = window.supabase.createClient(cfg.SUPABASE_URL, cfg.SUPABASE_ANON_KEY);
  try {
    var s = await sb.from("site_settings").select("*").eq("id",1).single();
    DATA.settings = s.data || {};
    DATA.courses = await q("courses");
    DATA.students = await q("students");
    DATA.certificates = await q("certificates");
    DATA.notices = await q("notices");
    DATA.gallery = await q("gallery_items");
    DATA.teachers = await q("teachers");
    DATA.achievements = await q("achievements");
    // Newest achievement date first (undated last, then newest entry first).
    DATA.achievements.sort(function(a, b){
      var da = a.achieved_date || "", db = b.achieved_date || "";
      if(da !== db) return da < db ? 1 : -1;
      var ca = a.created_at || "", cb = b.created_at || "";
      return ca < cb ? 1 : (ca > cb ? -1 : 0);
    });
    DATA.stories = await q("success_stories");
    DATA.slides = await q("slideshow_items");
    dataLoaded = true;
    return true;
  } catch(e){ return false; }
}
function subscribeRealtime(){
  if(!sb) return;
  try {
    sb.channel("sb-public").on("postgres_changes", {event:"*", schema:"public"}, function(){ loadData().then(renderPublic); }).subscribe();
  } catch(e){}
}

/* ---------- language + navigation (template layout) ---------- */
function applyLang(){
  document.querySelectorAll("[data-i18n]").forEach(function(el){ el.textContent = t(el.getAttribute("data-i18n")); });
  document.querySelectorAll("[data-i18n-ph]").forEach(function(el){ el.placeholder = t(el.getAttribute("data-i18n-ph")); });
  document.querySelectorAll("[data-i18n-aria]").forEach(function(el){ el.setAttribute("aria-label", t(el.getAttribute("data-i18n-aria"))); });
  document.querySelectorAll(".lang-btn").forEach(function(b){
    var on = b.getAttribute("data-lang")===currentLang;
    b.classList.toggle("on", on); b.setAttribute("aria-pressed", on ? "true" : "false");
  });
  document.documentElement.lang = currentLang;
}
function setLang(l){ if(l!=="bn"&&l!=="en"&&l!=="ja") l="bn"; currentLang=l; try{ localStorage.setItem("sbvtc_lang", l); }catch(e){} applyLang(); renderPublic(); }
function showView(view){
  document.getElementById("view-home").style.display = view==="home" ? "" : "none";
  document.querySelectorAll("section.page").forEach(function(sec){ sec.classList.toggle("on", sec.id==="view-"+view); });
  document.querySelectorAll("nav.main button[data-nav]").forEach(function(b){ b.classList.toggle("on", b.getAttribute("data-nav")===view); });
  var nav = document.getElementById("mainnav"); if(nav) nav.classList.remove("open");
  window.scrollTo(0,0);
}
document.addEventListener("click", function(e){
  var navBtn = e.target.closest("[data-nav]");
  if(navBtn){ e.preventDefault(); showView(navBtn.getAttribute("data-nav")); return; }
  var gal = e.target.closest("[data-gal]");
  if(gal){ var img = gal.querySelector("img"); var lb=document.getElementById("lightbox"); if(lb){ document.getElementById("lb-img").src = img ? img.src : ""; document.getElementById("lb-cap").textContent = gal.querySelector("figcaption") ? gal.querySelector("figcaption").textContent : ""; lb.classList.add("open"); } return; }
  var dl = e.target.closest("[data-download-cert]");
  if(dl){ e.preventDefault(); downloadIssuedCertificate(dl.getAttribute("data-download-cert"), dl); }
});

document.addEventListener("DOMContentLoaded", function(){
  document.querySelectorAll(".lang-btn").forEach(function(b){ b.addEventListener("click", function(){ setLang(b.getAttribute("data-lang")); }); });
  var burger = document.getElementById("burger");
  if(burger) burger.addEventListener("click", function(){ document.getElementById("mainnav").classList.toggle("open"); });
  var lbClose = document.getElementById("lb-close");
  if(lbClose) lbClose.addEventListener("click", function(){ document.getElementById("lightbox").classList.remove("open"); });
  var lb = document.getElementById("lightbox");
  if(lb) lb.addEventListener("click", function(e){ if(e.target===lb) lb.classList.remove("open"); });
  var bs = document.getElementById("btn-search"); if(bs) bs.addEventListener("click", doSearch);
  var sr = document.getElementById("search-roll"); if(sr) sr.addEventListener("keydown", function(e){ if(e.key==="Enter") doSearch(); });
  var bv = document.getElementById("btn-verify"); if(bv) bv.addEventListener("click", doVerify);
  var vl = document.getElementById("verify-license"); if(vl) vl.addEventListener("keydown", function(e){ if(e.key==="Enter") doVerify(); });
  var prev = document.getElementById("ss-prev"); if(prev) prev.addEventListener("click", function(){ goSlide(ssIdx-1); });
  var next = document.getElementById("ss-next"); if(next) next.addEventListener("click", function(){ goSlide(ssIdx+1); });
  applyLang(); renderPublic();
  var hideLoader = function(){ var l = document.getElementById("page-loader"); if(l) l.style.display = "none"; };
  // Safety: never trap the page behind the loader if data fails to load.
  loadData().then(function(){ applyLang(); renderPublic(); subscribeRealtime(); handleVerifyParam(); hideLoader(); }, hideLoader);
});

/* ---------- render helpers (template markup) ---------- */
function infoVal(field, fallback){
  var s = DATA.settings || {};
  var map = { name:"centre_name", tagline:"tagline", headline:"hero_title", lead:"hero_sub", about:"about", hours:"hours" };
  var col = map[field];
  if(!col) return fallback;
  if(currentLang==="bn") return s[col+"_bn"] || s[col] || fallback;
  var v = s[col+"_"+currentLang];
  if(v) return v;
  if(INFO_T[currentLang] && INFO_T[currentLang][field]) return INFO_T[currentLang][field];
  return fallback;
}
function courseFor(level){
  var sup = (DATA.courses||[]).find(function(c){ return (c.id||c.level||"").toString().toUpperCase()===level; });
  if(currentLang==="bn"){
    var bn = BN_COURSES[level] || {};
    return { title: (sup&&sup.title_bn)||bn.title||("Basic Japanese Language Course — "+level),
      forWhom: (sup&&sup.audience_bn)||bn.forWhom||"", duration: (sup? ((sup.duration_months||3)+" months") : bn.duration||"3 months"),
      hours: (sup? ((sup.hours||180)+"+ hours") : bn.hours||"180+ hours"),
      desc: (sup&&sup.description_bn)||bn.desc||"", topics: bn.topics||[] };
  }
  var ct = (COURSE_T[currentLang]||{})[level] || {};
  return { title: (sup&&sup["title_"+currentLang])||ct.title||("Course — "+level),
    forWhom: (sup&&sup["audience_"+currentLang])||ct.forWhom||"",
    duration: (sup? ((sup.duration_months||3)+" months") : ct.duration||""),
    hours: (sup? ((sup.hours||180)+"+ hours") : ct.hours||""),
    desc: (sup&&sup["description_"+currentLang])||ct.desc||"", topics: ct.topics||[] };
}
function courseCardHTML(level, detail){
  var c = courseFor(level);
  var topics = c.topics.map(function(x){ return "<li>"+esc(x)+"</li>"; }).join("");
  return '<article class="course-card'+(detail?" course-detail":"")+'">'+
    '<div class="course-top"><div class="level-badge">'+level+'<small>JAPANESE LANGUAGE</small></div><span class="pill">'+esc(c.forWhom)+'</span></div>'+
    '<div class="body"><h3 style="margin:0;font-size:1.14rem">'+esc(c.title)+'</h3>'+
    '<div class="meta-line"><span>'+t("duration_label")+'<b>'+esc(c.duration)+'</b></span><span>'+t("total_label")+'<b>'+esc(c.hours)+'</b></span></div>'+
    '<p>'+esc(c.desc)+'</p>'+
    (detail ? '<ul class="topics">'+topics+'</ul>' : "")+
    (detail ? "" : '<div class="foot"><button class="btn btn-navy btn-sm" data-nav="courses">'+t("course_detail_btn")+'</button></div>')+
    '</div></article>';
}
function noticeHTML(n){
  var iso = n.notice_date || n.date || "";
  var p = iso.split("-"); var day = p.length===3 ? fmtNum(p[2]) : "—"; var mon = "";
  if(p.length===3){ if(currentLang==="ja") mon = p[0]+"年"+(+p[1])+"月"; else if(currentLang==="en") mon = MONTHS_EN[+p[1]-1]+" "+p[0]; else mon = MONTHS_BN[+p[1]-1]+" "+bnNum(p[0]); }
  return '<article class="notice-item"><div class="notice-date"><b>'+day+'</b><span>'+mon+'</span></div><div><h3>'+esc(n.title)+'</h3><p>'+esc(n.body)+'</p></div></article>';
}
function galHTML(g){ return '<figure class="gal-item" data-gal="'+esc(g.id)+'" style="margin:0"><img src="'+esc(g.src)+'" alt="'+esc(g.caption||t("gallery_photo"))+'" loading="lazy" /><figcaption>'+esc(g.caption||"")+'</figcaption></figure>'; }
function studentCardHTML(s){
  return '<div class="result-card ok" style="margin-bottom:14px"><div class="result-flex">'+
    (s.photo ? '<img class="result-photo" src="'+esc(s.photo)+'" alt="'+esc(s.name)+'" />' : "")+
    '<div style="flex:1;min-width:220px"><h4>'+esc(s.name)+(s.status ? ' <span class="badge-ok">'+esc(s.status)+'</span>' : "")+'</h4>'+
    '<div class="kv">'+
    '<div><span>'+t("label_roll")+'</span><b>'+esc(s.roll)+'</b></div>'+
    (s.father ? '<div><span>'+t("label_father")+'</span><b>'+esc(s.father)+'</b></div>' : "")+
    '<div><span>'+t("label_course")+'</span><b>'+esc(s.course)+'</b></div>'+
    (s.batch ? '<div><span>'+t("label_batch")+'</span><b>'+esc(s.batch)+'</b></div>' : "")+
    (s.session ? '<div><span>'+t("label_session")+'</span><b>'+esc(s.session)+'</b></div>' : "")+
    '</div></div></div></div>';
}

/* ---------- slideshow (template track/dots, Supabase first, samples as fallback) ---------- */
var ssIdx = 0, ssTimer = null, ssTypes = [];
function ytEmbed(u){ return ytEmbedUrl(u); }
function slideshowItems(){
  var slides = [];
  var video = (DATA.slides||[]).find(function(x){ return x.kind==="video" && x.video_url; });
  if(video){
    var emb = ytEmbed(video.video_url);
    if(emb) slides.push({kind:"video", html:'<iframe src="'+esc(emb)+'" title="Video" allow="accelerometer; encrypted-media; picture-in-picture" allowfullscreen loading="lazy"></iframe>'});
    else if(/\.(mp4|webm|ogg|mov)(\?|#|$)/i.test(video.video_url)) slides.push({kind:"video", html:'<video controls playsinline preload="metadata" src="'+esc(video.video_url)+'"></video>'});
    else slides.push({kind:"video", html:'<iframe src="'+esc(video.video_url)+'" title="Video" allowfullscreen loading="lazy"></iframe>'});
  }
  var pics = (DATA.slides||[]).filter(function(x){ return x.kind==="image" && x.image_url; });
  pics.forEach(function(p){ slides.push({kind:"img", html:'<img src="'+esc(p.image_url)+'" alt="'+esc(p.title||"")+'" loading="lazy" />'+(p.title?'<div class="ss-cap">'+esc(p.title)+'</div>':"")}); });
  if(!slides.length){
    var gal = (DATA.gallery||[]).length ? DATA.gallery.map(function(g){ return {src:g.image_url, caption:g.caption}; }) : SAMPLE_GALLERY;
    gal.forEach(function(p){ slides.push({kind:"img", html:'<img src="'+esc(p.src)+'" alt="'+esc(p.caption||"")+'" loading="lazy" />'+(p.caption?'<div class="ss-cap">'+esc(p.caption)+'</div>':"")}); });
  }
  return slides;
}
function stopSS(){ if(ssTimer){ clearInterval(ssTimer); ssTimer=null; } }
function startSS(){ stopSS(); if(ssTypes[ssIdx]!=="video" && !window.matchMedia("(prefers-reduced-motion: reduce)").matches){ ssTimer=setInterval(function(){ goSlide(ssIdx+1); }, 4500); } }
function renderSlideshow(){
  var track=document.getElementById("ss-track"); var dots=document.getElementById("ss-dots"); var wrap=document.getElementById("slideshow");
  if(!track||!dots||!wrap) return;
  var slides = slideshowItems(); ssTypes = slides.map(function(s){ return s.kind; });
  if(!slides.length){ wrap.style.display="none"; stopSS(); return; }
  wrap.style.display="";
  if(ssIdx>=slides.length) ssIdx=0;
  track.innerHTML = slides.map(function(s){ return '<div class="ss-slide">'+s.html+'</div>'; }).join("");
  dots.innerHTML = slides.map(function(_,i){ return '<button type="button" class="ss-dot'+(i===ssIdx?" on":"")+'" data-ss-dot="'+i+'" aria-label="Slide '+(i+1)+'"></button>'; }).join("");
  dots.querySelectorAll("[data-ss-dot]").forEach(function(b){ b.addEventListener("click", function(){ goSlide(+b.getAttribute("data-ss-dot")); }); });
  track.style.transform = "translateX(-"+(ssIdx*100)+"%)";
  startSS();
}
function goSlide(i){ var track=document.getElementById("ss-track"); if(!track) return; var n = ssTypes.length; if(!n) return; ssIdx=((i%n)+n)%n; renderSlideshow(); }

