    sg.innerHTML = st.length ? st.map(function(x){ return '<article class="success-card">'+(x.photo_url?'<img class="success-photo" src="'+esc(x.photo_url)+'" alt="'+esc(x.student_name)+'" />':'<div class="success-photo success-photo-ph">'+esc((x.student_name||"?").charAt(0))+'</div>')+'<div class="success-body"><h3>'+esc(x.student_name)+'</h3><p class="success-story">'+esc(x.story||"")+'</p></div></article>'; }).join("") : '<div class="empty-note">'+t("empty_success")+'</div>';
