/* ---------- QR verification ---------- */
function verifyUrl(lic){ return "https://sbvtcdtc.github.io/SB-Centre-Website/?verify=" + encodeURIComponent(lic); }
async function setCertQR(imgEl, lic){
  if(!imgEl) return;
  if(!lic){ imgEl.removeAttribute("src"); return; }
  var url = "";
  if(typeof QRCode !== "undefined"){
    try { url = await QRCode.toDataURL(verifyUrl(lic), {width:192, margin:1}); } catch(e){}
  }
  if(!url){ url = "https://api.qrserver.com/v1/create-qr-code/?size=192x192&margin=4&data=" + encodeURIComponent(verifyUrl(lic)); imgEl.crossOrigin = "anonymous"; }
  // Wait for the image to actually load before returning, otherwise
  // html2canvas captures the QR area before the image appears (blank box).
  await new Promise(function(res){
    var done = false;
    var fin = function(){ if(!done){ done = true; res(); } };
    imgEl.onload = fin; imgEl.onerror = fin;
    imgEl.src = url;
    if(imgEl.complete && imgEl.naturalWidth) fin();
    setTimeout(fin, 3000);
  });
}
function handleVerifyParam(){
  var v = null;
  try { v = new URLSearchParams(window.location.search).get("verify"); } catch(e){}
  if(!v) return;
  var input = document.getElementById("verify-license");
  if(input) input.value = v;
  showView("verify");
  doVerify();
}

/* ---------- search + verify ---------- */
function doSearch(){
  var q = document.getElementById("search-roll").value.trim().toLowerCase();
  var box = document.getElementById("search-result");
  if(!q){ box.innerHTML = '<div class="result-card bad"><h4>'+t("search_enter_h")+'</h4><p style="margin:0">'+t("search_enter_p")+'</p></div>'; return; }
  var students = (DATA.students||[]).map(function(x){ return {roll:x.roll, name:x.name, father:"", course:x.course||"", batch:x.batch||"", session:x.session||"", status:x.status||"", photo:x.photo_url||""}; });
  var exact = students.filter(function(x){ return (x.roll||"").trim().toLowerCase()===q; });
  var matches = exact.length ? exact : students.filter(function(x){ return (x.name||"").toLowerCase().indexOf(q)!==-1 || (x.roll||"").toLowerCase().indexOf(q)!==-1; });
  if(!matches.length){ box.innerHTML = '<div class="result-card bad"><h4><span class="badge-bad">'+t("notfound_badge")+'</span></h4><p style="margin:0">'+t("notfound_p")+'</p></div>'; return; }
  box.innerHTML = matches.map(studentCardHTML).join("");
}
function doVerify(){
  var lic = document.getElementById("verify-license").value.trim().toLowerCase();
  var box = document.getElementById("verify-result");
  if(!lic){ box.innerHTML = '<div class="result-card bad"><h4>'+t("verify_enter_h")+'</h4><p style="margin:0">'+t("verify_enter_p")+'</p></div>'; return; }
  var c = (DATA.certificates||[]).find(function(x){ return String(x.license_no||"").trim().toLowerCase()===lic; });
  if(!c){ box.innerHTML = '<div class="result-card bad"><h4><span class="badge-bad">'+t("invalid_badge")+'</span></h4><p style="margin:0">'+t("invalid_p")+'</p></div>'; return; }
  var period = "";
  if(c.start_date && c.end_date) period = fmtDateEn(c.start_date)+" – "+fmtDateEn(c.end_date);
  box.innerHTML = '<div class="result-card ok"><h4><span class="badge-ok">'+t("valid_badge")+'</span></h4>'+
    '<div class="kv">'+
    '<div><span>'+t("label_name")+'</span><b>'+esc(c.student_name)+'</b></div>'+
    '<div><span>'+t("label_license")+'</span><b>'+esc(c.license_no)+'</b></div>'+
    '<div><span>'+t("label_level")+'</span><b>LEVEL – '+esc(c.level)+'</b></div>'+
    '<div><span>'+t("label_course")+'</span><b>'+esc(c.course_name)+' ('+esc(c.hours)+' hours)</b></div>'+
    (period?'<div><span>'+t("label_period")+'</span><b>'+esc(period)+'</b></div>':"")+
    '<div><span>'+t("label_issue")+'</span><b>'+fmtDateLoc(c.issue_date)+'</b></div>'+
    '<div><span>'+t("label_issuer")+'</span><b>'+esc((DATA.settings&&DATA.settings.centre_name)||"SB Vocational Training Centre")+'</b></div>'+
    '</div>'+
    '<div style="margin-top:14px;text-align:center"><img id="verify-qr-img" style="width:96px;height:96px" alt="Scan to verify" /><div style="font-size:.85rem">Scan to verify</div><div style="font-size:.75rem;word-break:break-all">'+esc(verifyUrl(c.license_no))+'</div></div>'+
    '<div class="verify-download"><p>'+t("download_cert_note")+'</p><button type="button" class="btn btn-red btn-sm" data-download-cert="'+esc(c.license_no)+'">'+t("download_cert")+'</button></div></div>';
  setCertQR(document.getElementById("verify-qr-img"), c.license_no);
}
function fmtDateJp(iso){
  if(!iso) return "";
  var a = String(iso).split("-");
  return a.length===3 ? a[0]+" 年 "+a[1]+" 月 "+a[2]+" 日" : iso;
}
function monthsWord(n){
  var w = ["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve"];
  return w[n] || String(n);
}
function certBodies(rec){
  var months = parseInt(rec.duration_months)||3;
  var hours = rec.hours||180;
  var course = rec.course_name||"Basic Japanese Language Course";
  var jp = "";
  if(rec.start_date && rec.end_date){
    jp = "あなたは当センターが主催する " + fmtDateJp(rec.start_date) + "から " + fmtDateJp(rec.end_date) + "まで " + String(months).padStart(2,"0") + " ヶ月間 " + hours + "時間以上の日本語能力講座の基礎課程を修了したことを証明いたします。";
  } else {
    jp = "あなたは当センターが主催する日本語能力講座の基礎課程を修了したことを証明いたします。";
  }
  var en = "This is to certify that the above-named trainee has successfully completed the " + course + " conducted by SB Vocational Training Centre, comprising a minimum of " + hours + " hours over a period of " + monthsWord(months) + " months.";
  return {jp:jp, en:en};
}

function fillDownloadCert(c){
  document.getElementById("rd-centre").textContent = (DATA.settings&&DATA.settings.centre_name)||"SB Vocational Training Centre";
  document.getElementById("rd-license").textContent = c.license_no || "—";
  document.getElementById("rd-level").textContent = c.level || "N5";
  document.getElementById("rd-name").textContent = c.student_name || "STUDENT NAME";
  var b = certBodies(c);
  document.getElementById("rd-body-jp").textContent = b.jp;
  document.getElementById("rd-body").textContent = b.en;
  document.getElementById("rd-date").textContent = fmtDateEn(c.issue_date);
  document.getElementById("rd-foot-level").textContent = c.level || "N5";
}
function downloadIssuedCertificate(license, btn){
  var c = (DATA.certificates||[]).find(function(x){ return String(x.license_no||"").trim().toLowerCase()===String(license||"").trim().toLowerCase(); });
  if(!c){ toast(t("invalid_p")); return; }
  if(typeof html2canvas==="undefined" || !window.jspdf){ toast(t("download_lib_missing")); return; }
  var orig = btn ? btn.innerHTML : "";
  if(btn){ btn.disabled=true; btn.textContent=t("downloading"); }
  fillDownloadCert(c);
  var node = document.getElementById("cert-download-node");
  setTimeout(async function(){
    await setCertQR(document.getElementById("rd-qr"), c.license_no);
    html2canvas(node, {scale:2, backgroundColor:"#fffdf6", useCORS:true}).then(function(canvas){
      var imgData = canvas.toDataURL("image/jpeg", 0.95);
      var jsPDF = window.jspdf.jsPDF;
      var pdf = new jsPDF({orientation:"landscape", unit:"mm", format:"a4"});
      pdf.addImage(imgData, "JPEG", 0, 0, 297, 210);
      pdf.save("Certificate-"+String(c.student_name||"Student").replace(/\s+/g,"_")+".pdf");
      if(btn){ btn.disabled=false; btn.innerHTML=orig; }
      toast(t("download_done"));
    }).catch(function(){ if(btn){ btn.disabled=false; btn.innerHTML=orig; } toast(t("download_failed")); });
  }, 80);
}
